-- INSERT UNIQUE BRANDS ONLY

-- First, clear existing test data
DELETE FROM public.brand_cache WHERE brand_code IN ('APOLLO', 'KFC', 'AMAZON', 'MYNTRA', 'BOOKMYSHOW', 'PIZZA', 'COSTA', 'DERMA', 'HEALTH', 'FLIPKART');

ON CONFLICT (brand_code) DO NOTHING;

-- Verify import
SELECT COUNT(*) as total_brands FROM public.brand_cache;
